// CE-4651 (U-18a) — the DDS plumbing of the Unreal image generator: CycloneDDS C + the DPS contract's C types, both GENERATED by
// scripts/unreal/dps_gen.py (git-ignored — the contract is still changing). Runtime module: the IG reads DPS in a game too, not only the editor.
using System.IO;
using UnrealBuildTool;

public class HrotDps : ModuleRules
{
	public HrotDps(ReadOnlyTargetRules Target) : base(Target)
	{
		PCHUsage = PCHUsageMode.UseExplicitOrSharedPCHs;
		CppCompileWarningSettings.UndefinedIdentifierWarningLevel = WarningLevel.Off;   // the generated .c and CycloneDDS headers test __GNUC__ etc. with #if
		PublicDependencyModuleNames.AddRange(new string[] { "Core", "CoreUObject", "Engine" });
		PrivateDependencyModuleNames.AddRange(new string[] { "Projects", "HrotTerrain", "Niagara", "Json", "InputCore" });   // the actors (AHrotVehicle); ⚠ HrotTerrain is an EDITOR module today (the importers share it) — fine for the editor-run IG, a split is needed before a packaged game

		string Third = Path.GetFullPath(Path.Combine(ModuleDirectory, "..", "ThirdParty", "CycloneDDS"));
		string Gen = Path.Combine(ModuleDirectory, "Private", "Generated");
		if (!File.Exists(Path.Combine(Third, "lib", "ddsc.lib")) || !File.Exists(Path.Combine(Gen, "DpsTopicTable.gen.inl")))
			throw new BuildException("HrotDps: run  python scripts/unreal/dps_gen.py  first (it makes ThirdParty/CycloneDDS and Private/Generated)");

		PrivateIncludePaths.Add(Path.Combine(Third, "include"));
		PrivateIncludePaths.Add(Gen);
		PublicAdditionalLibraries.Add(Path.Combine(Third, "lib", "ddsc.lib"));
		PublicDelayLoadDLLs.Add("ddsc.dll");   // loaded by full path in StartupModule (a delay-loaded dll is not looked up in the plugin's folder)
		RuntimeDependencies.Add("$(BinaryOutputDir)/ddsc.dll", Path.Combine(Third, "bin", "ddsc.dll"));
	}
}
